//! Typed identities and base attributes for every species.

use crate::error::AssetError;
use crate::type_chart::Type;

macro_rules! define_id_constants {
    ($id:ident, $kind:literal; $($name:ident = $value:literal),+ $(,)?) => {
        impl $id {
            $(
                #[doc = concat!("The stable ", $kind, " identity for `", stringify!($name), "`.")]
                pub const $name: $id = $id($value);
            )+
        }
    };
}

/// A stable index into [`SpeciesTable`].
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SpeciesId(pub u16);

impl SpeciesId {
    /// Returns the numeric table index.
    #[must_use]
    pub const fn index(self) -> u16 {
        self.0
    }
}

