/// A species' experience-growth curve.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum GrowthRate {
    /// Medium-fast growth.
    MediumFast = 0,
    /// Erratic growth.
    Erratic = 1,
    /// Fluctuating growth.
    Fluctuating = 2,
    /// Medium-slow growth.
    MediumSlow = 3,
    /// Fast growth.
    Fast = 4,
    /// Slow growth.
    Slow = 5,
}

/// A breeding egg group.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum EggGroup {
    /// No egg group, used by the reserved species slot.
    None = 0,
    /// Monster egg group.
    Monster = 1,
    /// Water 1 egg group.
    Water1 = 2,
    /// Bug egg group.
    Bug = 3,
    /// Flying egg group.
    Flying = 4,
    /// Field egg group.
    Field = 5,
    /// Fairy egg group.
    Fairy = 6,
    /// Grass egg group.
    Grass = 7,
    /// Human-like egg group.
    HumanLike = 8,
    /// Water 3 egg group.
    Water3 = 9,
    /// Mineral egg group.
    Mineral = 10,
    /// Amorphous egg group.
    Amorphous = 11,
    /// Water 2 egg group.
    Water2 = 12,
    /// Ditto egg group.
    Ditto = 13,
    /// Dragon egg group.
    Dragon = 14,
    /// Species that cannot produce eggs.
    NoEggsDiscovered = 15,
}

/// A species' Pokédex body colour.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum BodyColor {
    /// Red body colour.
    Red = 0,
    /// Blue body colour.
    Blue = 1,
    /// Yellow body colour.
    Yellow = 2,
    /// Green body colour.
    Green = 3,
    /// Black body colour.
    Black = 4,
    /// Brown body colour.
    Brown = 5,
    /// Purple body colour.
    Purple = 6,
    /// Gray body colour.
    Gray = 7,
    /// White body colour.
    White = 8,
    /// Pink body colour.
    Pink = 9,
}

/// How a species' gender is distributed.
///
/// Mixed ratios retain their stored female weight out of 256.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum GenderRatio {
    /// The species has no gender.
    Genderless,
    /// Every member is male.
    AlwaysMale,
    /// Every member is female.
    AlwaysFemale,
    /// The stored female weight out of 256.
    Ratio(u8),
}

impl GenderRatio {
    /// One-eighth female.
    pub const ONE_EIGHTH_FEMALE: GenderRatio = GenderRatio::Ratio(31);
    /// One-quarter female.
    pub const ONE_QUARTER_FEMALE: GenderRatio = GenderRatio::Ratio(63);
    /// One-half female.
    pub const HALF_FEMALE: GenderRatio = GenderRatio::Ratio(127);
    /// Three-quarters female.
    pub const THREE_QUARTERS_FEMALE: GenderRatio = GenderRatio::Ratio(191);

    /// Returns the stored gender-ratio byte.
    #[must_use]
    pub const fn raw(self) -> u8 {
        match self {
            Self::Genderless => 0xFF,
            Self::AlwaysMale => 0x00,
            Self::AlwaysFemale => 0xFE,
            Self::Ratio(n) => n,
        }
    }
}

/// Effort values awarded when the species is defeated.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct EvYield {
    /// HP EVs awarded.
    pub hp: u8,
    /// Attack EVs awarded.
    pub attack: u8,
    /// Defense EVs awarded.
    pub defense: u8,
    /// Speed EVs awarded.
    pub speed: u8,
    /// Special Attack EVs awarded.
    pub sp_attack: u8,
    /// Special Defense EVs awarded.
    pub sp_defense: u8,
}

impl EvYield {
    /// Largest value representable by each stored EV-yield field.
    pub const MAX_PER_STAT: u8 = 3;
}

/// Numeric and categorical base attributes for one species.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct BaseStats {
    /// Base HP stat.
    pub hp: u8,
    /// Base Attack stat.
    pub attack: u8,
    /// Base Defense stat.
    pub defense: u8,
    /// Base Speed stat.
    pub speed: u8,
    /// Base Special Attack stat.
    pub sp_attack: u8,
    /// Base Special Defense stat.
    pub sp_defense: u8,
    /// The species' one or two types (a single-type species repeats its type).
    pub types: [Type; 2],
    /// Catch rate (`0..=255`; higher is easier).
    pub catch_rate: u8,
    /// Base experience yield.
    pub base_exp: u8,
    /// Effort values awarded on defeat.
    pub ev_yield: EvYield,
    /// Common wild held item, or [`ItemId::NONE`].
    pub held_common: ItemId,
    /// Rare wild held item, or [`ItemId::NONE`].
    pub held_rare: ItemId,
    /// Gender distribution.
    pub gender_ratio: GenderRatio,
    /// Egg cycles (steps-to-hatch counter, in units of 255 steps).
    pub egg_cycles: u8,
    /// Base friendship a caught member starts with.
    pub base_friendship: u8,
    /// Experience-growth curve.
    pub growth_rate: GrowthRate,
    /// The species' one or two egg groups.
    pub egg_groups: [EggGroup; 2],
    /// Possible abilities; the second is [`AbilityId::NONE`] when absent.
    pub abilities: [AbilityId; 2],
    /// Safari-zone flee rate.
    pub safari_flee_rate: u8,
    /// Pokédex body colour.
    pub body_color: BodyColor,
    /// Prevents horizontal sprite flipping when set.
    pub no_flip: bool,
}

/// Number of entries in the species table.
pub const SPECIES_COUNT: usize = 412;

macro_rules! define_species {
    ($($name:ident = $index:literal => $base_stats:expr),+ $(,)?) => {
        impl SpeciesId {
            $(
                #[doc = concat!("The stable species identity for `", stringify!($name), "`.")]
                pub const $name: SpeciesId = SpeciesId($index);
            )+
        }

        const SPECIES_DATA: [BaseStats; SPECIES_COUNT] = [$($base_stats,)+];

        #[cfg(test)]
        const SPECIES_IDENTITIES: [SpeciesId; SPECIES_COUNT] = [$(SpeciesId::$name,)+];
    };
}

